{
  "tools": [
    {
      "name": "module_new",
      "description": "Create a new empty module",
      "inputSchema": {
        "type": "object",
        "properties": {
          "channels": {
            "type": "integer",
            "description": "Even channel count 2..32"
          },
          "name": {
            "type": "string",
            "description": "Song name"
          }
        },
        "additionalProperties": false
      }
    },
    {
      "name": "module_load",
      "description": "Load a module from disk",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string"
          }
        },
        "required": [
          "path"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "module_info",
      "description": "Return current module metadata",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "additionalProperties": false
      }
    },
    {
      "name": "pattern_set_cell",
      "description": "Set one pattern cell",
      "inputSchema": {
        "type": "object",
        "properties": {
          "pattern": {
            "type": "integer"
          },
          "row": {
            "type": "integer"
          },
          "channel": {
            "type": "integer"
          },
