      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string"
          },
          "format": {
            "type": "string",
            "enum": [
              "xm",
              "mod"
            ]
          }
        },
        "required": [
          "path"
        ],
        "additionalProperties": false
      }
    },
